def _is_frozen():
    if getattr(sys, "frozen", False):
        return True
    try:
        return bool(__compiled__)
    except NameError:
        pass
    exe = os.path.basename(sys.executable).lower()
    return exe not in ("python.exe","pythonw.exe","python","pythonw","python3.exe","python3")

def _find_base():
    candidates = []
    try: candidates.append(os.path.dirname(os.path.abspath(sys.argv[0])))
    except: pass
    try: candidates.append(os.getcwd())
    except: pass
    try: candidates.append(os.path.dirname(os.path.abspath(sys.executable)))
    except: pass
    extended = []
    for c in candidates:
        cur = c
        for _ in range(4):
            if cur not in extended: extended.append(cur)
            p = os.path.dirname(cur)
            if p == cur: break
            cur = p
    for d in extended:
        if os.path.isdir(os.path.join(d, "data")):
            return d
    return extended[0] if extended else os.path.dirname(os.path.abspath(__file__))

BASE_PATH = _find_base()

def _p(*parts):
    return os.path.join(BASE_PATH, *parts)

