def _parse_ver(v):
    v = v.strip().lstrip("v")
    try: return tuple(int(x) for x in v.split("."))
    except: return (0,0,0)

def _read_local_version():
    vf = _p("version.txt")
    if os.path.isfile(vf):
        try:
            with open(vf, "r", encoding="utf-8") as f:
                return f.read().strip()
        except: pass
    return FALLBACK_VERSION

def _write_local_version(v):
    try:
        with open(_p("version.txt"), "w", encoding="utf-8") as f:
            f.write(v.strip())
    except: pass

