def _get_hwid():
    if platform.system() != "Windows":
        return "N/A"
    try:
        import winreg
        k = winreg.OpenKey(winreg.HKEY_LOCAL_MACHINE,
                           r"SOFTWARE\Microsoft\Cryptography", 0,
                           winreg.KEY_READ | winreg.KEY_WOW64_64KEY)
        guid, _ = winreg.QueryValueEx(k, "MachineGuid")
        winreg.CloseKey(k)
        return hashlib.sha256(guid.strip().encode()).hexdigest()
    except:
        return "N/A"

def _load_saved_credentials():
    """Read encrypted credentials from data/credentials/.login-credentials"""
    cred_file = _p("data", "credentials", ".login-credentials")
    if not os.path.isfile(cred_file):
        return None
    try:
        import base64
        from cryptography.fernet import Fernet
        from cryptography.hazmat.primitives import hashes
        from cryptography.hazmat.primitives.kdf.pbkdf2 import PBKDF2HMAC

        hwid = _get_hwid()
        machine_key = hashlib.sha256(hwid.encode()).digest()
        kdf = PBKDF2HMAC(algorithm=hashes.SHA256(), length=32,
                         salt=b'FluxMarten_Salt_2026', iterations=100000)
        key = base64.urlsafe_b64encode(kdf.derive(machine_key))
        fernet = Fernet(key)

        with open(cred_file, "rb") as f:
            encrypted = f.read()
        decrypted = fernet.decrypt(encrypted)
        creds = json.loads(decrypted.decode())
        if creds.get("username") and creds.get("password"):
            return creds
    except:
        pass
    return None

