import requests as _req

# ═════════════════════════════════════════════════════════════════════════════
#  INFINITYFREE BOT-PROTECTION BYPASS
# ═════════════════════════════════════════════════════════════════════════════

import re as _re
from curl_cffi import requests as _curl_req
from cryptography.hazmat.primitives.ciphers import Cipher as _Cipher
from cryptography.hazmat.primitives.ciphers import algorithms as _alg, modes as _modes

_update_session = None  # reusable session with solved cookie

def _solve_infinityfree_challenge(session, url):
    """Solve InfinityFree's AES cookie challenge and return the authenticated session."""
    r = session.get(url, timeout=15)
    if "toNumbers" not in r.text:
        return r  # No challenge — direct response

    # Extract AES parameters from the challenge page
    a = _re.search(r'var a=toNumbers\("([a-f0-9]+)"\)', r.text)
    b = _re.search(r'b=toNumbers\("([a-f0-9]+)"\)', r.text)
    c = _re.search(r'c=toNumbers\("([a-f0-9]+)"\)', r.text)
    if not (a and b and c):
        return r  # Can't parse — return as-is

    # AES-128-CBC decrypt: key=a, iv=b, ciphertext=c
    key = bytes.fromhex(a.group(1))
    iv  = bytes.fromhex(b.group(1))
    ct  = bytes.fromhex(c.group(1))
    cipher = _Cipher(_alg.AES(key), _modes.CBC(iv))
    dec = cipher.decryptor()
    cookie_val = (dec.update(ct) + dec.finalize()).hex()

    # Set cookie and retry
    session.cookies.set("__test", cookie_val, domain=url.split("//")[1].split("/")[0])
    return session.get(url + ("&" if "?" in url else "?") + "i=1", timeout=15)


def _get_update_session():
    """Get or create a curl_cffi session with Chrome TLS fingerprint."""
    global _update_session
    if _update_session is None:
        _update_session = _curl_req.Session(impersonate="chrome")
    return _update_session


class _KeyAuth:
    def __init__(self):
        self.sessionid = ""
        self.initialized = False

    def init(self):
        r = _req.post(_KA_API, data={
            "type":"init","ver":_KA_VERSION,"hash":"",
            "name":_KA_NAME,"ownerid":_KA_OWNER
        }, timeout=10)
        if r.text == "KeyAuth_Invalid":
            raise Exception("Application not found")
        j = r.json()
        if not j.get("success"):
            raise Exception(j.get("message","Init failed"))
        self.sessionid = j["sessionid"]
        self.initialized = True

    def login(self, user, pwd):
        hwid = _get_hwid()
        r = _req.post(_KA_API, data={
            "type":"login","username":user,"pass":pwd,"hwid":hwid,
            "sessionid":self.sessionid,"name":_KA_NAME,"ownerid":_KA_OWNER
        }, timeout=10)
        j = r.json()
        if not j.get("success"):
            raise Exception(j.get("message","Login failed"))
        return True

# ═════════════════════════════════════════════════════════════════════════════
#  UPDATE LOGIC
# ═════════════════════════════════════════════════════════════════════════════

def _check_update():
    """Returns dict with version info or None."""
    try:
        session = _get_update_session()
        r = _solve_infinityfree_challenge(session, f"{_UPDATE_URL}/api/version")
        if r.status_code == 200:
            return r.json()
    except:
        pass
    return None

def _download_update(dest_path, progress_cb=None):
    """Download update.zip to dest_path with progress callback."""
    session = _get_update_session()
    r = session.get(f"{_UPDATE_URL}/api/download", stream=True, timeout=300)
    if "toNumbers" in (r.text if hasattr(r, 'text') and not isinstance(r.content[:4], bytes) else ""):
        r = _solve_infinityfree_challenge(session, f"{_UPDATE_URL}/api/download")
    r.raise_for_status()
    total = int(r.headers.get("content-length", 0))
    downloaded = 0
    with open(dest_path, "wb") as f:
        for chunk in r.iter_content(chunk_size=65536):
            if chunk:
                f.write(chunk)
                downloaded += len(chunk)
                if progress_cb and total:
                    progress_cb(downloaded, total)

def _verify_sha256(filepath, expected_hash):
    """Verify SHA256 hash of a file."""
    h = hashlib.sha256()
    with open(filepath, "rb") as f:
        for chunk in iter(lambda: f.read(65536), b""):
            h.update(chunk)
    return h.hexdigest().lower() == expected_hash.lower()

def _fmt_size(b):
    if b < 1024: return f"{b} B"
    if b < 1024**2: return f"{b/1024:.1f} KB"
    return f"{b/1024**2:.1f} MB"

def _is_protected(path):
    """Check if a path should be skipped during update."""
    normalized = path.replace("\\", "/")
    for prefix in PROTECTED_PREFIXES:
        p = prefix.replace("\\", "/")
        if normalized.startswith(p) or normalized == p.rstrip("/"):
            return True
    return False

def _backup_files():
    """Backup current app files to _backup/."""
    backup_dir = _p("_backup")
    if os.path.isdir(backup_dir):
        shutil.rmtree(backup_dir, ignore_errors=True)
    os.makedirs(backup_dir, exist_ok=True)

    items_to_backup = [
        "FluxMart.exe", "MSK_core", "static", "templates",
        "browserforge_data", "version.txt", "start.bat",
        "gui_main.py", "main.py",
    ]
    for item in items_to_backup:
        src = _p(item)
        dst = os.path.join(backup_dir, item)
        if os.path.isdir(src):
            shutil.copytree(src, dst, dirs_exist_ok=True)
        elif os.path.isfile(src):
            os.makedirs(os.path.dirname(dst), exist_ok=True)
            shutil.copy2(src, dst)

def _install_update(zip_path):
    """Extract update ZIP replacing only app files and removing old ones."""
    temp_dir = _p("_update_temp", "extracted")
    os.makedirs(temp_dir, exist_ok=True)

    with zipfile.ZipFile(zip_path, "r") as zf:
        zf.extractall(temp_dir)

    # 1. Delete old files that are not in the new update
    for root, dirs, files in os.walk(BASE_PATH):
        # Skip walking into protected or temp directories to save time
        dirs[:] = [d for d in dirs if not _is_protected(os.path.relpath(os.path.join(root, d), BASE_PATH))]
        for fname in files:
            full = os.path.join(root, fname)
            rel = os.path.relpath(full, BASE_PATH)
            if _is_protected(rel):
                continue
            # If file doesn't exist in the extracted update, delete it
            if not os.path.isfile(os.path.join(temp_dir, rel)):
                try:
                    os.remove(full)
                except:
                    pass

    # 2. Walk extracted files and copy non-protected ones
    for root, dirs, files in os.walk(temp_dir):
        for fname in files:
            full = os.path.join(root, fname)
            rel = os.path.relpath(full, temp_dir)
            if _is_protected(rel):
                continue
            dst = _p(rel)
            os.makedirs(os.path.dirname(dst), exist_ok=True)
            shutil.copy2(full, dst)
        for dname in dirs:
            full = os.path.join(root, dname)
            rel = os.path.relpath(full, temp_dir)
            if _is_protected(rel):
                continue
            os.makedirs(_p(rel), exist_ok=True)

def _rollback():
    """Restore files from _backup/."""
    backup_dir = _p("_backup")
    if not os.path.isdir(backup_dir):
        return False
    for root, dirs, files in os.walk(backup_dir):
        for fname in files:
            src = os.path.join(root, fname)
            rel = os.path.relpath(src, backup_dir)
            dst = _p(rel)
            os.makedirs(os.path.dirname(dst), exist_ok=True)
            shutil.copy2(src, dst)
    return True

def _cleanup():
    """Remove temp and backup dirs."""
    for d in ("_update_temp", "_backup"):
        p = _p(d)
        if os.path.isdir(p):
            shutil.rmtree(p, ignore_errors=True)

def _write_lock(version_from, version_to):
    with open(_p("update.lock"), "w", encoding="utf-8") as f:
        json.dump({"stage":"installing","from":version_from,
                    "to":version_to,"ts":time.time()}, f)

def _remove_lock():
    lf = _p("update.lock")
    if os.path.isfile(lf):
        os.remove(lf)

def _read_lock():
    lf = _p("update.lock")
    if os.path.isfile(lf):
        try:
            with open(lf, "r", encoding="utf-8") as f:
                return json.load(f)
        except: pass
    return None

def _launch_app():
    """Launch the main application."""
    exe = _p("FluxMart.exe")
    if os.path.isfile(exe):
        subprocess.Popen([exe], cwd=BASE_PATH,
                         creationflags=0x00000008 if sys.platform=="win32" else 0)
        return True
        
    bat = _p("start.bat")
    if os.path.isfile(bat):
        subprocess.Popen([bat], cwd=BASE_PATH,
                         creationflags=0x00000008 if sys.platform=="win32" else 0)
        return True

    gm = _p("gui_main.py")
    if os.path.isfile(gm):
        # When frozen with Nuitka, sys.executable is the Bootstrapper.exe itself!
        # Do not use sys.executable here to avoid an infinite loop of it opening itself.
        python_exe = "pythonw" if sys.platform=="win32" else "python3"
        subprocess.Popen([python_exe, gm], cwd=BASE_PATH,
                         creationflags=0x08000000 if sys.platform=="win32" else 0)
        return True
    return False

# ═════════════════════════════════════════════════════════════════════════════
#  BOOTSTRAPPER API (pywebview JS API)
# ═════════════════════════════════════════════════════════════════════════════

import webview

class BootstrapperAPI:
    def __init__(self):
        self._window = None
        self._remote = None   # server version info
        self._local_ver = ""
        self._ka = None

    def set_window(self, w):
        self._window = w

    def _js(self, code):
        if self._window:
            try: self._window.evaluate_js(code)
            except: pass

    # ── Called by frontend on load ───────────────────────────────────────
    def start(self):
        threading.Thread(target=self._run_flow, daemon=True).start()

    def _run_flow(self):
        try:
            # Step 0: Crash recovery
            lock = _read_lock()
            if lock:
                self._js("showScreen('recovery')")
                time.sleep(0.5)
                if os.path.isdir(_p("_backup")):
                    self._js("setStatus('recovery-status','Restoring previous version...','')")
                    _rollback()
                    _remove_lock()
                    _cleanup()
                    self._js("setStatus('recovery-status','Restored! Launching app...','success')")
                    time.sleep(1.5)
                    _launch_app()
                    time.sleep(0.5)
                    self._close()
                    return
                else:
                    _remove_lock()

            # Step 1: Show splash
            self._js("showScreen('splash')")
            self._js("setStatus('splash-status','Initializing...','')")
            time.sleep(0.5)

            # Step 2: Read credentials
            creds = _load_saved_credentials()

            if not creds:
                # No saved credentials — show login form
                self._js("showScreen('login')")
                return  # flow continues when user clicks Login

            # Step 3: Auto-login with saved credentials
            self._js("showScreen('keycheck')")
            self._js("setStatus('keycheck-status','Checking your key...','')")
            time.sleep(0.3)

            ok = self._do_keyauth(creds["username"], creds["password"])
            if not ok:
                self._js("showScreen('login')")
                self._js("setStatus('login-status','Saved credentials invalid. Please log in.','error')")
                return

            self._js("setStatus('keycheck-status','Valid!','success')")
            time.sleep(0.8)

            # Step 4: Check for updates
            self._check_and_prompt()

        except Exception as e:
            self._js(f"setError('Connection Error','{str(e)[:200]}')")

    def _do_keyauth(self, user, pwd):
        try:
            self._ka = _KeyAuth()
            self._ka.init()
            self._ka.login(user, pwd)
            return True
        except Exception as e:
            return False

    def _check_and_prompt(self):
        self._js("showScreen('keycheck')")
        self._js("setStatus('keycheck-status','Checking for updates...','')")
        time.sleep(0.5)

        self._local_ver = _read_local_version()
        self._remote = _check_update()

        if not self._remote or "version" not in self._remote:
            # Can't reach server — launch anyway
            self._js(f"setUptodateVer('{self._local_ver}')")
            self._js("showScreen('uptodate')")
            time.sleep(2)
            _launch_app()
            time.sleep(0.5)
            self._close()
            return

        remote_ver = self._remote["version"]
        if _parse_ver(remote_ver) > _parse_ver(self._local_ver):
            # Update available
            size = self._remote.get("size", "")
            self._js(f"setUpdateInfo('{self._local_ver}','{remote_ver}','{size}')")
            self._js("showScreen('update')")
        else:
            # Up to date
            _write_local_version(self._local_ver)
            # Clean leftover backup from previous successful update
            if os.path.isdir(_p("_backup")):
                _cleanup()
            self._js(f"setUptodateVer('{self._local_ver}')")
            self._js("showScreen('uptodate')")
            time.sleep(2)
            _launch_app()
            time.sleep(0.5)
            self._close()

    # ── Login (called from frontend) ────────────────────────────────────
    def login(self, username, password):
        try:
            self._js("showScreen('keycheck')")
            self._js("setStatus('keycheck-status','Checking your key...','')")

            ok = self._do_keyauth(username, password)
            if not ok:
                self._js("showScreen('login')")
                return {"success": False, "error": "Invalid credentials"}

            self._js("setStatus('keycheck-status','Valid!','success')")
            time.sleep(0.8)

            # Check updates in background
            threading.Thread(target=self._check_and_prompt, daemon=True).start()
            return {"success": True}
        except Exception as e:
            return {"success": False, "error": str(e)[:200]}

    # ── Download + Install (called from frontend) ───────────────────────
    def download_update(self):
        threading.Thread(target=self._do_download, daemon=True).start()

    def _do_download(self):
        try:
            self._js("showScreen('progress')")
            self._js("setStatus('progress-status','Downloading update...','')")

            remote_ver = self._remote["version"]
            expected_hash = self._remote.get("sha256", "")

            # Download
            temp_dir = _p("_update_temp")
            os.makedirs(temp_dir, exist_ok=True)
            zip_path = os.path.join(temp_dir, "update.zip")

            def on_progress(dl, total):
                pct = (dl / total) * 100
                self._js(f"setProgress({pct:.1f},'{_fmt_size(dl)}','{_fmt_size(total)}')")

            _download_update(zip_path, on_progress)
            self._js("setProgress(100,'','Complete')")
            time.sleep(0.3)

            # Verify SHA256
            self._js("setStatus('progress-status','Verifying integrity...','')")
            time.sleep(0.3)
            if expected_hash and not _verify_sha256(zip_path, expected_hash):
                self._js("setError('Verification Failed','Download corrupted. SHA256 mismatch. Please try again.')")
                shutil.rmtree(temp_dir, ignore_errors=True)
                return

            # Backup
            self._js("setStatus('progress-status','Backing up current files...','')")
            time.sleep(0.3)
            _backup_files()

            # Write lock
            _write_lock(self._local_ver, remote_ver)

            # Install
            self._js("setStatus('progress-status','Installing update...','')")
            time.sleep(0.3)
            _install_update(zip_path)

            # Remove lock
            _remove_lock()

            # Write new version
            _write_local_version(remote_ver)

            # Cleanup temp
            shutil.rmtree(temp_dir, ignore_errors=True)

            # Done
            self._js("showScreen('complete')")
            time.sleep(2)

            # Launch and health check
            _launch_app()
            time.sleep(3)

            # Clean backup (app launched successfully)
            _cleanup()
            time.sleep(0.5)
            self._close()

        except Exception as e:
            # Try rollback
            if os.path.isdir(_p("_backup")):
                _rollback()
            _remove_lock()
            shutil.rmtree(_p("_update_temp"), ignore_errors=True)
            self._js(f"setError('Update Failed','{str(e)[:200]}')")

    # ── Skip / Launch / Retry / Close ───────────────────────────────────
    def skip_update(self):
        threading.Thread(target=self._do_skip, daemon=True).start()

    def _do_skip(self):
        _launch_app()
        time.sleep(0.5)
        self._close()

    def launch_app(self):
        threading.Thread(target=self._do_skip, daemon=True).start()

    def retry(self):
        threading.Thread(target=self._run_flow, daemon=True).start()

    def minimize_window(self):
        if self._window:
            self._window.minimize()

    def close_window(self):
        self._close()

    def _close(self):
        if self._window:
            try: self._window.destroy()
            except: pass
        os._exit(0)


